const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;

const dx = [0, 0, -1, 1, -1, 1, -1, 1];
const dy = [1, -1, 0, 0, 1, 1, -1, -1];

const MAX = 5 * 30 + 5;

// marked[2 * MAX][2 * MAX][8][32][6]
const marked = [];
for (let a = 0; a < 2 * MAX; a++) {
  marked[a] = [];
  for (let b = 0; b < 2 * MAX; b++) {
    marked[a][b] = [];
    for (let c = 0; c < 8; c++) {
      marked[a][b][c] = [];
      for (let d = 0; d < 32; d++) {
        marked[a][b][c][d] = new Array(6).fill(false);
      }
    }
  }
}

const mp = new Map();
const t = new Array(100).fill(0);

function rot(dir) {
  if (dir === UP)
    return [UPLEFT, UPRIGHT];
  if (dir === DOWN)
    return [DOWNLEFT, DOWNRIGHT];
  if (dir === LEFT)
    return [UPLEFT, DOWNLEFT];
  if (dir === RIGHT)
    return [UPRIGHT, DOWNRIGHT];
  if (dir === UPLEFT)
    return [UP, LEFT];
  if (dir === UPRIGHT)
    return [UP, RIGHT];
  if (dir === DOWNLEFT)
    return [DOWN, LEFT];
  if (dir === DOWNRIGHT)
    return [DOWN, RIGHT];
}

class Node {
  constructor(_x, _y, _dir, _lev, _far) {
    this.x = _x;
    this.y = _y;
    this.dir = _dir;
    this.lev = _lev;
    this.far = _far;
  }
}

class Queue {
  constructor() {
    this.data = [];
    this.head = 0;
  }
  push(x) {
    this.data.push(x);
  }
  pop() {
    this.head++;
  }
  front() {
    return this.data[this.head];
  }
  empty() {
    return this.head >= this.data.length;
  }
}

function main(input) {
  const tokens = input.trim().split(/\s+/).map(Number);
  let idx = 0;
  const n = tokens[idx++];
  for (let i = 1; i <= n; i++) {
    t[i] = tokens[idx++];
  }

  let ans = 0;
  const Q = new Queue();
  Q.push(new Node(MAX, MAX, UP, 1, 1));

  marked[MAX][MAX][UP][1][1] = true;
  mp.set(`${MAX},${MAX}`, true);
  ans++;

  while (!Q.empty()) {
    const v = Q.front();
    Q.pop();

    const key = `${v.x},${v.y}`;
    if (!mp.has(key)) {
      mp.set(key, true);
      ans++;
    }

    const lev = v.lev;
    const far = v.far;

    let x2 = v.x, y2 = v.y;

    if (lev === n + 1)
      continue;

    if (far !== t[lev]) {
      x2 += dx[v.dir];
      y2 += dy[v.dir];
      if (marked[x2][y2][v.dir][lev][far + 1]) continue;
      marked[x2][y2][v.dir][lev][far + 1] = true;
      Q.push(new Node(x2, y2, v.dir, lev, far + 1));
    } else {
      const dirs = rot(v.dir);
      if (!marked[v.x][v.y][dirs[0]][lev + 1][0]) {
        marked[v.x][v.y][dirs[0]][lev + 1][0] = true;
        Q.push(new Node(v.x, v.y, dirs[0], lev + 1, 0));
      }
      if (!marked[v.x][v.y][dirs[1]][lev + 1][0]) {
        marked[v.x][v.y][dirs[1]][lev + 1][0] = true;
        Q.push(new Node(v.x, v.y, dirs[1], lev + 1, 0));
      }
    }
  }

  return ans.toString() + "\n";
}

